"use strict";

/**
 * Counting and comparing `gamenode/no-hard-coded-colors` violations against
 * the legacy baseline (`color-baseline.json`). Used by `bin/colors.js`
 * (`pnpm colors:check` / `pnpm colors:baseline`).
 *
 * Counting is independent of the ESLint severity: the rule is forced on as
 * `error` with the same off patterns as the real configs (tests, theme
 * definitions, generated files), so the numbers equal "violations if the
 * file were not in the baseline". CSS files are counted with the CSS checker.
 * `theme-exempt` exemptions are honored by both.
 */

const fs = require("node:fs");
const path = require("node:path");

const { registerGamenodePlugin } = require("./plugin-resolver");
const { lintCssColors } = require("./css-colors");
const {
  BASELINE_FILE,
  COLOR_ENFORCED_PACKAGES,
  COLOR_RULE_OFF_PATTERNS,
  loadColorBaseline,
} = require("./hard-coded-colors");

const RULE_ID = "gamenode/no-hard-coded-colors";
const REPO_ROOT = path.resolve(__dirname, "../..");

function toPosix(value) {
  return value.split(path.sep).join("/");
}

/**
 * Counts violations per repo-relative file for the given packages. Packages
 * default to every enforced one (ui, web, mobile).
 */
async function countColorViolations({
  repoRoot = REPO_ROOT,
  packages = COLOR_ENFORCED_PACKAGES,
} = {}) {
  registerGamenodePlugin();
  const { ESLint } = require("eslint");

  const counts = {};

  for (const pkg of packages) {
    const cwd = path.join(repoRoot, pkg);
    if (!fs.existsSync(path.join(cwd, "src"))) continue;

    const eslint = new ESLint({
      cwd,
      useEslintrc: false,
      extensions: [".ts", ".tsx"],
      overrideConfig: {
        root: true,
        parser: require.resolve("@typescript-eslint/parser"),
        parserOptions: {
          ecmaFeatures: { jsx: true },
          ecmaVersion: "latest",
          sourceType: "module",
        },
        plugins: ["gamenode"],
        rules: { [RULE_ID]: "error" },
        overrides: [
          {
            files: [...COLOR_RULE_OFF_PATTERNS],
            rules: { [RULE_ID]: "off" },
          },
        ],
      },
    });

    const results = await eslint.lintFiles(["src"]);

    for (const result of results) {
      const relFile = toPosix(path.relative(repoRoot, result.filePath));
      let count = 0;

      for (const message of result.messages) {
        if (message.ruleId === RULE_ID) count += 1;
        else if (message.fatal) {
          throw new Error(
            `${relFile}:${message.line}:${message.column} ${message.message}`,
          );
        }
      }

      if (count > 0) counts[relFile] = count;
    }

    const css = lintCssColors({ cwd, roots: ["src"], repoRoot });

    for (const message of css.messages) {
      counts[message.file] = (counts[message.file] ?? 0) + 1;
    }
  }

  return sortCounts(counts);
}

function sortCounts(counts) {
  return Object.fromEntries(
    Object.entries(counts).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
  );
}

/**
 * Compares current counts with the baseline.
 *  - `added`: files outside the baseline that have violations (fail);
 *  - `grown`: baseline files whose count increased (fail);
 *  - `shrunk`: baseline files with fewer (or no) violations (allowed).
 * `scope` limits the comparison to the baseline entries under the scanned
 * packages, so a per-package check does not report other packages as shrunk.
 */
function compareWithBaseline(
  counts,
  baseline,
  packages = COLOR_ENFORCED_PACKAGES,
) {
  const inScope = (file) => packages.some((pkg) => file.startsWith(`${pkg}/`));

  const added = [];
  const grown = [];
  const shrunk = [];

  for (const [file, count] of Object.entries(counts)) {
    if (!Object.prototype.hasOwnProperty.call(baseline, file)) {
      added.push({ file, count });
    } else if (count > baseline[file]) {
      grown.push({ file, count, baseline: baseline[file] });
    } else if (count < baseline[file]) {
      shrunk.push({ file, count, baseline: baseline[file] });
    }
  }

  for (const [file, baselineCount] of Object.entries(baseline)) {
    if (inScope(file) && !(file in counts)) {
      shrunk.push({ file, count: 0, baseline: baselineCount });
    }
  }

  return { added, grown, shrunk };
}

function writeBaseline(counts, file = BASELINE_FILE) {
  const payload = {
    _comment:
      "Generated by `pnpm colors:baseline` (packages/config-eslint/bin/colors.js). Do not edit by hand. Legacy files that still bypass the theme: they stay `warn` and may only shrink. Everything else is `error`.",
    files: sortCounts(counts),
  };

  fs.writeFileSync(file, `${JSON.stringify(payload, null, 2)}\n`);
}

module.exports = {
  REPO_ROOT,
  compareWithBaseline,
  countColorViolations,
  loadColorBaseline,
  writeBaseline,
};
